from pathlib import Path
import argparse, json, html
from openpyxl import load_workbook

DEFAULT_INPUT=Path(r'C:\MPFM\NOVO\data\outputs\MPFM_JUN_2026.xlsx')

def read_sheet(ws):
    rows=list(ws.iter_rows(values_only=True))
    if not rows: return []
    heads=[str(v).strip() if v is not None else '' for v in rows[0]]
    out=[]
    for values in rows[1:]:
        row={h:values[i] if i<len(values) else None for i,h in enumerate(heads) if h}
        if row.get('ProductionDate') is None and row.get('day_ref') is None and row.get('Dia') is None: continue
        out.append({k:(v.isoformat() if hasattr(v,'isoformat') else v) for k,v in row.items()})
    return out

def build(source, output):
    wb=load_workbook(source,read_only=True,data_only=True)
    data={name:read_sheet(wb[name]) for name in wb.sheetnames}
    payload={'source':str(source),'pi_available':False,'sheets':data}
    blob=json.dumps(payload,ensure_ascii=False,separators=(',',':'))
    page='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MPFM Junho 2026</title><style>:root{--blue:#073763;--line:#d7e1ea}*{box-sizing:border-box}body{margin:0;background:#f4f7fa;color:#102238;font:14px Segoe UI,Arial}header{background:linear-gradient(110deg,#062b59,#12639a);color:#fff;padding:22px 30px;border-bottom:4px solid #d7263d}h1{margin:5px 0}main{max-width:1500px;margin:auto;padding:22px}.notice,.panel{background:#fff;border:1px solid var(--line);border-radius:9px;padding:15px;margin-bottom:14px}.notice{background:#e8f4fb;border-left:4px solid #1769aa}.tabs{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0}button,select{font:inherit;padding:8px 11px;border:1px solid #b9c8d6;border-radius:7px;background:#fff;cursor:pointer}button.active,button:hover{background:#1769aa;color:#fff}.panel{display:none}.panel.active{display:block}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:10px 0}.table-wrap{overflow:auto;max-height:650px;border:1px solid var(--line)}table{border-collapse:collapse;min-width:100%}th,td{padding:7px 9px;border-bottom:1px solid #e2e8f0;white-space:nowrap}th{position:sticky;top:0;background:#073763;color:#fff;text-align:left}tr:nth-child(even){background:#f8fbfd}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.kpi{background:#fff;border-left:5px solid #087f8c;border-radius:8px;padding:12px}.kpi b{display:block;font-size:22px;margin-top:5px}</style></head><body><header>Metering Management | Bacalhau<h1>MPFM Junho 2026 — Controle independente</h1><div>MPFM_JUN_2026.xlsx · sem PI · separado da Base Única Total</div></header><main><div class="notice"><b>Escopo:</b> leitura preservando as colunas originais. Daily, Hourly, MPFM e Separador permanecem separados.</div><div class="tabs"><button class="active" data-tab="resumo">Resumo</button><button data-tab="daily">Daily</button><button data-tab="hourly">Hourly</button><button data-tab="sep">Separador</button><button data-tab="recon">Reconciliação</button><button data-tab="alertas">Alertas</button><button data-tab="status">Status mensal</button></div><section id="resumo" class="panel active"><h2>Resumo</h2><div id="kpis" class="kpis"></div><p>Os dados são exclusivamente do arquivo informado. PI não está disponível nesta base.</p></section><section id="daily" class="panel"><h2>Dados diários</h2><div class="controls"><select id="dt"><option value="ALL">Todos os tipos</option><option>Topside</option><option>Subsea</option></select><select id="do"><option value="ALL">Todas as origens</option><option>MPFM</option><option>SEP</option></select></div><div id="dailyTable"></div></section><section id="hourly" class="panel"><h2>Dados horários</h2><div class="controls"><select id="ht"><option value="ALL">Todos os tipos</option><option>Topside</option><option>Subsea</option></select><select id="ho"><option value="ALL">Todas as origens</option><option>MPFM</option><option>SEP</option></select></div><div id="hourlyTable"></div></section><section id="sep" class="panel"><h2>Separador de testes</h2><div id="sepTable"></div></section><section id="recon" class="panel"><h2>Reconciliação</h2><div id="reconTable"></div></section><section id="alertas" class="panel"><h2>Alertas</h2><div id="alertTable"></div></section><section id="status" class="panel"><h2>Status mensal</h2><div id="statusTable"></div></section></main><script>const DATA=__DATA__;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const rows=n=>DATA.sheets[n]||[];function draw(id,a){const e=document.getElementById(id);if(!a.length){e.innerHTML='<p>Sem dados.</p>';return}const cs=Object.keys(a[0]);e.innerHTML='<div class="table-wrap"><table><thead><tr>'+cs.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+a.map(r=>'<tr>'+cs.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}function filt(n,t,o){let a=rows(n),tv=document.getElementById(t)?.value,ov=document.getElementById(o)?.value;if(tv&&tv!='ALL')a=a.filter(r=>r.Tipo==tv);if(ov&&ov!='ALL')a=a.filter(r=>r.Origin==ov);return a}function render(){let d=rows('DAILYS'),h=rows('HOURLYS');draw('dailyTable',filt('DAILYS','dt','do'));draw('hourlyTable',filt('HOURLYS','ht','ho'));draw('sepTable',d.concat(h).filter(r=>r.Origin=='SEP'));draw('reconTable',rows('RECON'));draw('alertTable',rows('ALERTAS_MES'));draw('statusTable',rows('STATUS_MES'));document.getElementById('kpis').innerHTML=[['Daily',d.length],['Hourly',h.length],['MPFM Daily',d.filter(r=>r.Origin=='MPFM').length],['MPFM Hourly',h.filter(r=>r.Origin=='MPFM').length],['SEP',d.concat(h).filter(r=>r.Origin=='SEP').length],['PI','Não disponível']].map(x=>'<div class="kpi"><span>'+x[0]+'</span><b>'+x[1]+'</b></div>').join('')}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});['dt','do','ht','ho'].forEach(id=>document.getElementById(id).onchange=render);render();</script></body></html>'''.replace('__DATA__',blob)
    output.write_text(page,encoding='utf-8'); print(output)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--input',type=Path,default=DEFAULT_INPUT);p.add_argument('--output',type=Path,default=Path(__file__).with_name('MPFM_JUN26_INDEPENDENTE.html'));a=p.parse_args();build(a.input,a.output)
